    // END MACHINE VECTORS
    private static byte[] saved(Pc1CrxMemory memory)throws IOException{ByteArrayOutputStream raw=new ByteArrayOutputStream();memory.save(new DataOutputStream(raw));return raw.toByteArray();}
    public static int run()throws Exception{
        count=0;check(VECTORS.length==72,"all actual machine programs");
        for(String vector:VECTORS){String[] f=vector.split("\\|",-1);String name=f[0];Pc1CrxMemory memory=memory();if(!f[4].isEmpty())for(String seed:f[4].split(";")){String[] s=seed.split(":");int address=Integer.parseInt(s[0]);byte[] raw=bytes(s[1]);for(int n=0;n<raw.length;n++)memory.write(address+n,raw[n]);}
            Input file=new Input(encoded(f[1]),Integer.parseInt(f[3]));Allocator allocation=new Allocator();Pc1CrxDecoder decoder=new Pc1CrxDecoder(memory);Pc1CrxDecoder.Decoded output=decoder.decode(file,allocation);int result=Integer.parseInt(f[2]);check((output==null)==(result==-1),name+" native return");
            if(output!=null){check(f[5].startsWith("@sha256:")?Binary.sha256(output.storage()).equals(f[5].substring(8)):Arrays.equals(output.storage(),bytes(f[5])),name+" every allocation byte including padding");check(output.width==Integer.parseInt(f[6])&&output.height==Integer.parseInt(f[7])&&output.stride==Integer.parseInt(f[8])&&output.format==Integer.parseInt(f[9]),name+" geometry and actual format");check(output.source()!=null,name+" typed source without ARGB");}
            byte[] image=saved(memory);check(Binary.sha256(Arrays.copyOfRange(image,4,image.length)).equals(f[10]),name+" full owned raw globals and stale buffer/window/palette");check(file.position==Integer.parseInt(f[11]),name+" CRT request consumption");check(!decoder.active()&&allocation.open==0,name+" call boundary and required frees");
            Pc1CrxMemory restored=memory();restored.restore(Pc1CrxMemory.loadImage(new DataInputStream(new ByteArrayInputStream(image))));check(Arrays.equals(saved(restored),image),name+" byte exact globals snapshot");
        }
        Pc1CrxMemory aliased=memory();aliased.write(Pc1CrxMemory.PALETTE+768,0x91);check(aliased.dword(Pc1CrxMemory.ROW_BYTES)==0x91,"palette index256 aliases native row byte DWORD rather than padded fake palette");aliased.write(0x454cd8,0x7e);check(aliased.read(0x454cd8)==0x7e,"settings remains borrowed canonical owner");boolean unknown=false;try{aliased.read(Pc1CrxMemory.ROW_POINTER);}catch(IOException expected){unknown=true;}check(unknown,"native heap row pointer is explicitly unowned, not invented zero/address");
        // A preceding literal resource changes the otherwise unwritten ring
        //suffix; replacing the decoder must not replace its canonical owner.
        Pc1CrxMemory shared=memory();shared.write(Pc1CrxMemory.WINDOW+65533,0x19);shared.write(Pc1CrxMemory.WINDOW+65534,0x2b);shared.write(Pc1CrxMemory.WINDOW+65535,0x3d);byte[] header=bytes("435258470000000001000100010001000000000000a3");Pc1CrxDecoder.Decoded replay=new Pc1CrxDecoder(shared).decode(new Input(header,-1),new Allocator());check(Arrays.equals(replay.storage(),bytes("192b3da5")),"unwritten initial ring reads stale canonical bytes across decoder instances");
        Pc1CrxMemory boundary=memory();Allocator underlying=new Allocator();Pc1CrxDecoder.Allocator guarded=new Pc1CrxDecoder.Allocator(){public Pc1CrxDecoder.Allocation image(int size)throws IOException{boolean saveRejected=false;try{saved(boundary);}catch(IOException expected){saveRejected=true;}check(saveRejected,"snapshot cannot omit native-call temporary allocations");boolean reentry=false;try{new Pc1CrxDecoder(boundary).decode(new Input(new byte[0],-1),underlying);}catch(IOException expected){reentry=expected.getMessage().contains("reentry");}check(reentry&&boundary.active(),"separate decoder cannot reset/reenter same canonical globals");return underlying.image(size);}public Pc1CrxDecoder.Allocation temporary(int size){return underlying.temporary(size);}};new Pc1CrxDecoder(boundary).decode(new Input(header,-1),guarded);check(!boundary.active()&&underlying.open==0,"outer native call commits/retires exactly once");
        Pc1CrxMemory eof=memory();for(int n=0;n<16;n++)eof.write(Pc1CrxMemory.BUFFER+n,255);byte[] onlyHeader=Arrays.copyOf(header,20);Pc1CrxDecoder.Input osError=new Pc1CrxDecoder.Input(){int calls;public int descriptor(){return 7;}public int read(byte[] raw,int offset,int requested){if(calls++==0){System.arraycopy(onlyHeader,0,raw,offset,20);return 20;}return -1;}};Pc1CrxDecoder.Decoded stale=new Pc1CrxDecoder(eof).decode(osError,new Allocator());check(Arrays.equals(stale.storage(),bytes("ffffffa5"))&&eof.dword(Pc1CrxMemory.BUFFER_COUNT)==-5,"LZ OS error continues actual stale byte reads and signed decrement");
        Pc1CrxMemory rejected=memory();byte[] before=saved(rejected);Pc1CrxDecoder.Input error=new Pc1CrxDecoder.Input(){public int descriptor(){return 7;}public int read(byte[] raw,int offset,int requested){return -1;}};check(new Pc1CrxDecoder(rejected).decode(error,new Allocator())==null&&Arrays.equals(before,saved(rejected)),"failed initial CRT read preserves exact old header/global bytes");
        Pc1CrxDecoder.Allocator missing=new Pc1CrxDecoder.Allocator(){public Pc1CrxDecoder.Allocation image(int size){return null;}public Pc1CrxDecoder.Allocation temporary(int size){throw new AssertionError("image allocation failed first");}};check(new Pc1CrxDecoder(rejected).decode(new Input(header,-1),missing)==null&&rejected.dword(Pc1CrxMemory.STRIDE)==0,"failed image allocation does not publish later stride/counters");
        return count;
    }
    public static void main(String[] args)throws Exception{System.out.println("Pc1CrxDecoderTests assertions: "+run());}
